+/**
+ * An abstract implementation of {@link AsyncTwoPhaseIndexer} that builds a rollup index incrementally.
+ */
+public class RollupV2Indexer extends AsyncTwoPhaseIndexer<Map<String, Object>, RollupIndexerJobStats> {
