+        testCase(aggregationBuilder, new MatchAllDocsQuery(), iw -> iw.addDocument(List.of()), r -> {
+            InternalAdjacencyMatrix result = (InternalAdjacencyMatrix) r;
+            assertThat(result.getBuckets(), equalTo(List.of()));
+        });
+    }
