+        AdjacencyMatrixAggregationBuilder aggregationBuilder = new AdjacencyMatrixAggregationBuilder(
+            "dummy",
+            Map.of("a", new MatchAllQueryBuilder(), "b", new MatchAllQueryBuilder())
+        );
