+            // Provide visibility guarantees for the modified queue
+            lock.lock();
+            try {
+                while (done == false && queue.isEmpty()) {
+                    condition.await();
+                }
+            } catch (InterruptedException e) {
+                cancelSubscription();
+                throw new RuntimeException(e);
+            } finally {
